//! Engine ABI v1 (ADR 0035): what an `engine.wasm` exports, and the plain-Rust logic behind it.
//!
//! Exports (generated by [`export_engine!`](crate::export_engine)): `kx_abi() -> u32`,
//! `kx_alloc(len) -> ptr`, `kx_free(ptr, len)`, `kx_run(ptr, len) -> u64` (high half: pointer of
//! the response frame, low half: its length; free it with `kx_free`). Request and response use
//! [`crate::frame`]. The host provides the `kx_host` imports (`now_ms`, `fill_random`,
//! `is_cancelled`, `progress`).
use crate::frame::{self, Failure};
use crate::{Cx, ToolError, ValueMap};

/// Version reported by `kx_abi`. It only grows on a breaking change.
pub const ABI_VERSION: u32 = 1;

/// Decodes `request`, runs the engine entry and encodes the response. Never panics on a
/// malformed request: it answers `worker_protocol`.
pub fn handle(
    request: &[u8],
    run: impl FnOnce(&ValueMap, &ValueMap, &mut Cx) -> Result<ValueMap, ToolError>,
) -> Vec<u8> {
    let outcome = match frame::decode_request(request) {
        Ok((inputs, params)) => run(&inputs, &params, &mut Cx::new()),
        Err(Failure { code, detail }) => Err(ToolError {
            code: frame::static_code(&code),
            detail,
        }),
    };
    frame::encode_response(&outcome)
}

/// `kx_alloc`: a buffer of `len` bytes in this module's memory.
#[cfg(target_arch = "wasm32")]
#[must_use]
pub fn alloc(len: u32) -> u32 {
    let mut buffer = Vec::<u8>::with_capacity(len as usize);
    let pointer = buffer.as_mut_ptr();
    std::mem::forget(buffer);
    pointer as u32
}

/// `kx_free`: releases a buffer from [`alloc`] or a response from [`run`].
#[cfg(target_arch = "wasm32")]
pub fn free(pointer: u32, len: u32) {
    // SAFETY: the host only frees pointers returned by `kx_alloc`/`kx_run` with their length;
    // both allocate exactly `len` bytes of capacity.
    unsafe {
        drop(Vec::from_raw_parts(
            pointer as *mut u8,
            len as usize,
            len as usize,
        ))
    }
}

/// `kx_run`: serves one request frame at `pointer`/`len`.
#[cfg(target_arch = "wasm32")]
pub fn run(
    pointer: u32,
    len: u32,
    entry: impl FnOnce(&ValueMap, &ValueMap, &mut Cx) -> Result<ValueMap, ToolError>,
) -> u64 {
    // SAFETY: the host wrote `len` bytes at `pointer` (obtained from `kx_alloc`).
    let request = unsafe { std::slice::from_raw_parts(pointer as *const u8, len as usize) };
    let mut response = handle(request, entry);
    response.shrink_to_fit();
    let (out, out_len) = (response.as_mut_ptr() as u64, response.len() as u64);
    std::mem::forget(response);
    (out << 32) | out_len
}

/// Exports the engine ABI from an engine crate: `kortex_runtime::export_engine!(tool::run_map);`.
/// Does nothing outside `wasm32`.
#[macro_export]
macro_rules! export_engine {
    ($run:path) => {
        #[cfg(target_arch = "wasm32")]
        #[unsafe(no_mangle)]
        pub extern "C" fn kx_abi() -> u32 {
            $crate::engine_abi::ABI_VERSION
        }

        #[cfg(target_arch = "wasm32")]
        #[unsafe(no_mangle)]
        pub extern "C" fn kx_alloc(len: u32) -> u32 {
            $crate::engine_abi::alloc(len)
        }

        #[cfg(target_arch = "wasm32")]
        #[unsafe(no_mangle)]
        pub extern "C" fn kx_free(pointer: u32, len: u32) {
            $crate::engine_abi::free(pointer, len);
        }

        #[cfg(target_arch = "wasm32")]
        #[unsafe(no_mangle)]
        pub extern "C" fn kx_run(pointer: u32, len: u32) -> u64 {
            $crate::engine_abi::run(pointer, len, |inputs, params, cx| {
                $crate::block_on($run(inputs, params, cx))
            })
        }
    };
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::Value;

    fn echo(inputs: &ValueMap, _: &ValueMap, _: &mut Cx) -> Result<ValueMap, ToolError> {
        Ok(inputs.clone())
    }

    #[test]
    fn handle_runs_the_engine_on_a_decoded_request() {
        let inputs = ValueMap::from([("text".to_owned(), Value::Text("a".to_owned()))]);
        let response = handle(&frame::encode_request(&inputs, &ValueMap::new()), echo);
        assert_eq!(frame::decode_response(&response), Ok(inputs));
    }

    #[test]
    fn handle_reports_engine_errors_and_bad_requests() {
        let failing = handle(
            &frame::encode_request(&ValueMap::new(), &ValueMap::new()),
            |_, _, _| Err(ToolError::new("empty_input")),
        );
        assert_eq!(
            frame::decode_response(&failing).map_err(|e| e.code),
            Err("empty_input".to_owned())
        );
        let garbage = handle(b"nope", echo);
        assert_eq!(
            frame::decode_response(&garbage).map_err(|e| e.code),
            Err("worker_protocol".to_owned())
        );
    }
}
